<?php require 'config.php';login_required();
$whereParts=[];$args=[];
if(user()['role_code']==='requester'){$whereParts[]='r.requester_id=?';$args[]=(int)user()['id'];}
$status=$_GET['status']??'';
$allowedStatuses=['draft','pending','approved','rejected','issued'];
if(in_array($status,$allowedStatuses,true)){$whereParts[]='r.status=?';$args[]=$status;}
$where=$whereParts?'WHERE '.implode(' AND ',$whereParts):'';
$s=db()->prepare("SELECT r.*,u.name requester FROM requests r JOIN users u ON u.id=r.requester_id $where ORDER BY r.id DESC");$s->execute($args);$rows=$s->fetchAll();?><!doctype html><html lang="<?=e(current_lang())?>"><head><?php include 'partials/head.php';?></head><body><?php include 'partials/nav.php';?><main class="container"><div class="page-head"><div><h2><?=e(t('requests'))?></h2><p><?=current_lang()==='th'?'ติดตามสถานะคำขอเบิกทั้งหมด':'Track and manage material requisitions'?></p></div><?php if(in_array(user()['role_code'],['requester','admin'],true)):?><a class="btn" href="request_new.php">＋ <?=e(t('new_request'))?></a><?php endif;?></div><?php if($status):?><div class="filter-note">กำลังแสดงเฉพาะสถานะ: <b><?=e(status_text($status))?></b> · <a href="requests.php">แสดงทั้งหมด</a></div><?php endif;?><div class="panel"><div class="table-wrap"><table class="table"><thead><tr><th><?=e(t('request_no'))?></th><th><?=e(t('requester'))?></th><th><?=e(t('department'))?></th><th><?=e(t('status'))?></th><th><?=e(t('current_step'))?></th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['request_no'])?></b></td><td><?=e($r['requester'])?></td><td><?=e($r['department'])?></td><td><span class="badge <?=e($r['status'])?>"><?=e(status_text($r['status']))?></span></td><td><?=e($r['current_level'])?> / 3</td><td><a href="request_view.php?id=<?=$r['id']?>"><?=e(t('view'))?> →</a></td></tr><?php endforeach;?></tbody></table></div></div></main></div></div></body></html>
